#| A greeting for one person.
def greet(name, greeting) {
    return greeting + ", " + name + "!"
}
print(greet("Ada", "hello"))
print(greet("Grace", "hi"))
print(greet("Alan", "good morning"))
# @@ several results
def min_max_mean(xs: Arr) {
    lo = py_bmin(xs)
    hi = py_bmax(xs)
    return lo, hi, py_div_f(py_lsum(xs), len(xs))
}
lo, hi, mean = min_max_mean([4.0, 1.0, 7.0, 2.0])
print(fmt(lo), fmt(hi), fmt(mean))
# @@ a function as an argument
def apply_twice(f, x) {
    return f(f(x))
}
def square(x) {
    return x * x
}
print(fmt(apply_twice(square, 3.0)))
def _lam29(x) {
    return x + 10.0
}
print(fmt(apply_twice(_lam29, 1.0)))
